89	    fn source(&self, id: FileId) -> FileResult<Source> {
90	        if id == self.main.id() {
91	            Ok(self.main.clone())
92	        } else if let Some(source) = self.files.sources.get(&id) {
93	            Ok(source.clone())
94	        } else {
95	            Err(FileError::NotFound(id.vpath().get_without_slash().into()))
96	        }
97	    }
98	
99	    fn file(&self, id: FileId) -> FileResult<Bytes> {
100	        match self.files.assets.get(&id) {
101	            Some(bytes) => Ok(bytes.clone()),
102	            None => Err(FileError::NotFound(id.vpath().get_without_slash().into())),
103	        }
104	    }
105	
106	    fn font(&self, index: usize) -> Option<Font> {
107	        self.base.fonts.get(index).cloned()
108	    }
109	
110	    fn today(&self, _: Option<Duration>) -> Option<Datetime> {
111	        None
112	    }
113	}
114	
115	impl IdeWorld for TestWorld {
116	    fn upcast(&self) -> &dyn World {
117	        self
118	    }
119	
120	    fn files(&self) -> Vec<FileId> {
121	        std::iter::once(self.main.id())
122	            .chain(self.files.sources.keys().copied())
123	            .chain(self.files.assets.keys().copied())
124	            .collect()
125	    }
126	
127	    fn packages(&self) -> &[(PackageSpec, Option<EcoString>)] {
128	        const LIST: &[(PackageSpec, Option<EcoString>)] = &[(
129	            PackageSpec {
130	                // NOTE: This literal, `"preview"`, should match the const, `DEFAULT_NAMESPACE`,
131	                // defined in `crates/typst-kit/src/package.rs`. However, we should always use the
132	                // literal here, not `DEFAULT_NAMESPACE`, so that this test fails if its value
133	                // changes in an unexpected way.
134	                namespace: EcoString::inline("preview"),
135	                name: EcoString::inline("example"),
136	                version: PackageVersion { major: 0, minor: 1, patch: 0 },
137	            },
138	            None,
139	        )];
140	        LIST
141	    }
142	}
143	
144	/// Test-specific files.
145	#[derive(Default, Clone)]
146	struct TestFiles {
147	    assets: FxHashMap<FileId, Bytes>,
148	    sources: FxHashMap<FileId, Source>,
149	}
150	
151	/// Shared foundation of all test worlds.
152	struct TestBase {
153	    library: LazyHash<Library>,
154	    book: LazyHash<FontBook>,
155	    fonts: Vec<Font>,
156	}
157	
158	impl Default for TestBase {
159	    fn default() -> Self {
160	        let fonts: Vec<_> = typst_assets::fonts()
161	            .chain(typst_dev_assets::fonts())
162	            .flat_map(|data| Font::iter(Bytes::new(data)))
163	            .collect();
164	
165	        Self {
166	            library: LazyHash::new(library()),
167	            book: LazyHash::new(FontBook::from_fonts(&fonts)),
168	            fonts,
169	        }
170	    }
171	}
172	
173	/// The extended standard library for testing.
174	fn library() -> Library {
175	    // Set page width to 120pt with 10pt margins, so that the inner page is
176	    // exactly 100pt wide. Page height is unbounded and font size is 10pt so
177	    // that it multiplies to nice round numbers.
178	    let mut lib = typst::Library::builder().with_features(Features::all()).build();
179	    lib.styles.set(PageElem::width, Smart::Custom(Abs::pt(120.0).into()));
180	    lib.styles.set(PageElem::height, Smart::Auto);
181	    lib.styles.set(
182	        PageElem::margin,
183	        Smart::Custom(Margin::splat(Some(Smart::Custom(Abs::pt(10.0).into())))),
184	    );
185	    lib.styles.set(TextElem::size, TextSize(Abs::pt(10.0).into()));
186	    lib
187	}
188	
189	/// The input to a test: Either just a string or a full `TestWorld`.
190	pub trait WorldLike {
191	    type World: Borrow<TestWorld>;
192	
193	    fn acquire(self) -> Self::World;
194	}
195	
196	impl<'a> WorldLike for &'a TestWorld {
197	    type World = &'a TestWorld;
198	
199	    fn acquire(self) -> Self::World {
200	        self
201	    }
202	}
203	
204	impl WorldLike for &str {
205	    type World = TestWorld;
206	
207	    fn acquire(self) -> Self::World {
208	        TestWorld::new(self)
209	    }
210	}
211	
212	/// Specifies a position in a file for a test. Negative numbers index from the
213	/// back. `-1` is at the very back.
214	pub trait FilePos {
215	    fn resolve(self, world: &TestWorld) -> (Source, usize);
216	}
217	
218	impl FilePos for isize {
219	    #[track_caller]
220	    fn resolve(self, world: &TestWorld) -> (Source, usize) {
221	        (world.main.clone(), cursor(&world.main, self))
222	    }
223	}
224	
225	impl FilePos for (&str, isize) {
226	    #[track_caller]
227	    fn resolve(self, world: &TestWorld) -> (Source, usize) {
228	        let id = RootedPath::new(VirtualRoot::Project, VirtualPath::new(self.0).unwrap())
229	            .intern();
230	        let source = world.source(id).unwrap();
231	        let cursor = cursor(&source, self.1);
232	        (source, cursor)
233	    }
234	}
235	
236	/// Resolve a signed index (negative from the back) to a unsigned index.
237	#[track_caller]
238	fn cursor(source: &Source, cursor: isize) -> usize {
239	    if cursor < 0 {
240	        source.text().len().checked_add_signed(cursor + 1).unwrap()
241	    } else {
242	        cursor as usize
243	    }
244	}
245	
246	/// A test function that is used in autocomplete & tooltip tests.
247	pub const EXAMPLE_CLOSURE: &str = "
248	// A *useful* function.
249	//
250	// With extra text.
251	#let foo(
252	    wood,
253	    /// Tree with three slashes.
254	    tree: 1,
255	    // More *trees*.
256	    //
257	    // More information, $1+2$.
258	    forest: rgb(\"#123\"),
259	) = (wood * tree, forest)
260	";
