333	/// Whether a rectangle with the given size at the given position contains the
334	/// click position.
335	fn is_in_rect(pos: Point, size: Size, click: Point) -> bool {
336	    pos.x <= click.x
337	        && pos.x + size.x >= click.x
338	        && pos.y <= click.y
339	        && pos.y + size.y >= click.y
340	}
